146:        /**
147:         * Configures SAXParserFactory with features required
148:         * to use external DTD file loading, this is not activated by default to no allow
149:         * usage of schema files that checkstyle do not know
150:         * it is even security problem to allow files from outside.
151:         *
152:         * @param factory factory to be configured with special features
153:         * @throws ParserConfigurationException if an error occurs
154:         * @throws SAXException if an error occurs
155:         */
156:        public static void setFeaturesBySystemProperty(SAXParserFactory factory)
157:                throws SAXException, ParserConfigurationException {
158:
159:            final boolean enableExternalDtdLoad = Boolean.parseBoolean(
160:                System.getProperty(ENABLE_EXTERNAL_DTD_LOAD, "false"));
